 Check(writes.Count==60,"opening editor writes every f3 cell through SDK callback");Check(editor.Rows.Count==12,"original trans+rot count");Check(editor.Rows[0].ImageX=="1.235","source f3 display");Check(editor.Table.ColumnHeaderHeight==30&&editor.Table.RowHeight==30,"source row geometry");Check(editor.TrySetCell(0,1,"3.5"),"immediate write");Check(writes.Last()==(0,1,"3.5"),"typed callback identity");reject=true;Check(!editor.TrySetCell(0,1,"4.5")&&editor.Rows[0].ImageY=="3.5","failed setter preserves old");reject=false;Check(!editor.TrySetCell(0,1,"bad"),"invalid value rejected by owner");
