 var owner=editor.CreateWindow();Check(owner.Width==493&&owner.Height==399&&owner.Content==editor,"source popup geometry");owner.ShowInTaskbar=false;owner.ShowActivated=false;owner.Left=-30000;owner.Top=-30000;owner.WindowStartupLocation=WindowStartupLocation.Manual;owner.Show();owner.UpdateLayout();Check(editor.Table.ActualWidth>0,"actual WPF visual measured");Directory.CreateDirectory("analysis/full-audit/n-point-configuration-controls");var bitmap=new RenderTargetBitmap(493,399,96,96,PixelFormats.Pbgra32);bitmap.Render(owner);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create("analysis/full-audit/n-point-configuration-controls/point-editor-source-derived.png"))png.Save(file);owner.Close();
 var xml="""<AlgorithmTabRoot><Tabs><Tab><Categorys><Category><Items><EditButton_Calib Name="RotPointTotalNum"><AccessMode>RW</AccessMode><CurValue>3</CurValue><MinValue>0</MinValue><MaxValue>16</MaxValue><IncValue>1</IncValue><SubscribeVisible>False</SubscribeVisible></EditButton_Calib><OpenFileForCalibDialog Name="CalibPathName"><AccessMode>RW</AccessMode><CurValue>old.xml</CurValue><SubscribeVisible>False</SubscribeVisible></OpenFileForCalibDialog></Items></Category></Categorys></Tab></Tabs></AlgorithmTabRoot>""";
 var state=new ToolConfigurationState(ToolConfigurationDefinition.Parse(xml));var registry=new ToolConfigurationControlRegistry();int editClicks=0,pathClicks=0;NPointConfigurationControls.Register(registry,_=>editClicks++,_=>pathClicks++);using var view=new ToolConfigurationView(state,registry);view.Measure(new Size(420,500));view.Arrange(new Rect(0,0,420,500));view.UpdateLayout();Check(view.Diagnostics.Count==0,"both original template keys routed");var editorButton=Walk(view).OfType<Button>().Single(b=>b.Name=="NPointEditPoints");editorButton.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(editClicks==1,"source editor button typed callback");Walk(view).OfType<Button>().Single(b=>b.Name=="NPointChooseCalibrationPath").RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(pathClicks==1,"source path button typed callback");Check(Walk(view).OfType<ConfigurationNumericSpinner>().Count()==1,"integer control is composed shared standard factory");Check(Walk(view).OfType<TextBox>().Any(t=>t.Text=="old.xml"),"file leaf editable text separate from browse icon");
 var failedDelete=new NPointConfigurationPointEditor(p,6,(_,_,_)=>true,_=>false,()=>true,()=>null,()=>null);Check(!failedDelete.DeletePoint(1)&&failedDelete.Rows.Count==5&&failedDelete.Rows[1].ID==2,"original delete rejection retains removed UI row before reindex");
 int partial=0;var failedImport=new NPointConfigurationPointEditor(p,12,(_,_,_)=>{partial++;return true;},_=>true,()=>true,()=>null,()=>null);partial=0;try{failedImport.ImportText("1 2 3 4 5\r\nbad 1 2 3 4\r\n");throw new Exception("expected malformed row");}catch(InvalidDataException){}Check(partial==5&&failedImport.Rows.Count==12,"original import preserves earlier SDK side effects while visible old list remains");

 var full=new NPointConfigurationPointEditor(p,12,(_,_,_)=>true,_=>true,()=>true,()=>null,()=>null);var fullWindow=full.CreateWindow();fullWindow.ShowInTaskbar=false;fullWindow.ShowActivated=false;fullWindow.WindowStartupLocation=WindowStartupLocation.Manual;fullWindow.Left=-30000;fullWindow.Top=-30000;fullWindow.Show();fullWindow.UpdateLayout();var fullImage=new RenderTargetBitmap(493,399,96,96,PixelFormats.Pbgra32);fullImage.Render(fullWindow);var fullPng=new PngBitmapEncoder();fullPng.Frames.Add(BitmapFrame.Create(fullImage));using(var fullFile=File.Create("analysis/full-audit/n-point-configuration-controls/point-editor-twelve-source-derived.png"))fullPng.Save(fullFile);Check(full.Table.Columns.Count==6,"original deletion lives outside six-column table");Check(Walk(full).OfType<ItemsControl>().Any(i=>i.Name=="deletItem"),"source template owns external delete list");fullWindow.Close();
 Console.WriteLine($"PASS {checks} N-point configuration control checks");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(root,i)))yield return child;}
